#![cfg(any(target_os="linux",target_os="android",target_os="macos"))]
#[path="support/provider_general.rs"]mod fixture;
#[path="support/resource_roots.rs"]mod root_fixture;
use fixture::*;
use std::{sync::atomic::Ordering,time::Duration};
use tokio::{sync::Mutex,time::timeout};
static LOCK:Mutex<()>=Mutex::const_new(());
fn filtered_payload(front:u16,exit:u16,suffix:&str)->String{format!("proxies:\n - {{name: front-{suffix},type: http,server: 127.0.0.1,port: {front}}}\n - {{name: exit-{suffix},type: http,server: 127.0.0.1,port: {exit},dialer-proxy: FRONT}}\n")}
#[tokio::test(flavor="multi_thread",worker_threads=4)]
async fn projected_filtered_slots_accept_legal_refresh_without_early_dial_and_forward_actual_new_hops(){
    let _serial=LOCK.lock().await;let roots=root_fixture::Roots::new();let mut servers=Servers::new();let a=servers.proxy().await;let b=servers.proxy().await;let c=servers.proxy().await;let d=servers.proxy().await;let target=servers.origin().await;
    let feed=servers.feed(filtered_payload(a.address.port(),b.address.port(),"old")).await;
    let yaml=format!("strict: true\nproxy-providers: {{feed: {{type: http,url: 'http://{}/feed',path: projected.yaml,interval: 0}}}}\nproxy-groups:\n - {{name: FRONT,type: select,use: [feed],filter: '^front-'}}\n - {{name: PICK,type: select,use: [feed],filter: '^exit-'}}\nrules: ['MATCH,PICK']\n",feed.address);
    let ports=ports().await;let(session,weak)=start(plan(&yaml,ports,&roots.read,&roots.cache));timeout(Duration::from_secs(5),session.ready()).await.unwrap().unwrap();
    assert!(a.targets.lock().unwrap().is_empty());assert!(b.targets.lock().unwrap().is_empty());roundtrip(ports[1],target).await;assert_eq!(a.targets.lock().unwrap().as_slice(),[b.address.to_string()]);assert_eq!(b.targets.lock().unwrap().as_slice(),[target.to_string()]);let before=get(ports[0],"/aerove/route").await;
    *feed.payload.write().await=filtered_payload(c.address.port(),d.address.port(),"new");let response=request(ports[0],"PUT","/providers/proxies/feed","").await;assert!(response.starts_with("HTTP/1.1 204"),"{response}");assert!(c.targets.lock().unwrap().is_empty(),"projection validation must not dial");assert!(d.targets.lock().unwrap().is_empty());
    let after=get(ports[0],"/aerove/route").await;assert_ne!(before["core-epoch"],after["core-epoch"]);assert_eq!(after["picks"]["FRONT"],"front-new");assert_eq!(after["picks"]["PICK"],"exit-new");assert_eq!(get(ports[0],"/providers/proxies/feed").await["revision"],"2");
    roundtrip(ports[1],target).await;assert_eq!(a.targets.lock().unwrap().len(),1);assert_eq!(b.targets.lock().unwrap().len(),1);assert_eq!(c.targets.lock().unwrap().as_slice(),[d.address.to_string()]);assert_eq!(d.targets.lock().unwrap().as_slice(),[target.to_string()]);
    stopped(&session,weak,ports).await;servers.close().await;
}
#[tokio::test(flavor="multi_thread",worker_threads=4)]
async fn projected_cycle_rejected_before_http_cache_userinfo_receipt_or_live_slot_changes(){
    let _serial=LOCK.lock().await;let roots=root_fixture::Roots::new();let mut servers=Servers::new();let a=servers.proxy().await;let b=servers.proxy().await;let target=servers.origin().await;let feed=servers.feed(filtered_payload(a.address.port(),b.address.port(),"good")).await;*feed.userinfo.write().await=Some("upload=1; download=2; total=1000; expire=4000000000".into());
    let yaml=format!("strict: true\nproxy-providers: {{feed: {{type: http,url: 'http://{}/feed',path: cycle-cache.yaml,interval: 0}}}}\nproxy-groups:\n - {{name: FRONT,type: select,use: [feed],filter: '^front-'}}\n - {{name: PICK,type: select,use: [feed],filter: '^exit-'}}\nrules: ['MATCH,PICK']\n",feed.address);let ports=ports().await;let(session,weak)=start(plan(&yaml,ports,&roots.read,&roots.cache));timeout(Duration::from_secs(5),session.ready()).await.unwrap().unwrap();
    let cache=std::fs::read(roots.cache.join("cycle-cache.yaml")).unwrap();let userinfo=std::fs::read(roots.cache.join("cycle-cache.yaml.subscription-userinfo")).unwrap();let receipt=get(ports[0],"/providers/proxies/feed").await;let stamp=get(ports[0],"/aerove/route").await;
    *feed.payload.write().await=format!("proxies:\n - {{name: front-loop,type: direct,dialer-proxy: FRONT}}\n - {{name: exit-loop,type: http,server: 127.0.0.1,port: {},dialer-proxy: FRONT}}\n",b.address.port());*feed.userinfo.write().await=Some("upload=900; download=901; total=9999; expire=4000000001".into());let response=request(ports[0],"PUT","/providers/proxies/feed","").await;assert!(!response.starts_with("HTTP/1.1 204"),"cyclic projected graph published");
    assert_eq!(std::fs::read(roots.cache.join("cycle-cache.yaml")).unwrap(),cache);assert_eq!(std::fs::read(roots.cache.join("cycle-cache.yaml.subscription-userinfo")).unwrap(),userinfo);let after=get(ports[0],"/providers/proxies/feed").await;assert_eq!(after["revision"],receipt["revision"]);assert_eq!(after["proxies"],receipt["proxies"]);assert_eq!(after["subscriptionInfo"],receipt["subscriptionInfo"]);assert_eq!(get(ports[0],"/aerove/route").await,stamp);assert!(a.targets.lock().unwrap().is_empty());assert!(b.targets.lock().unwrap().is_empty());roundtrip(ports[1],target).await;assert_eq!(a.targets.lock().unwrap().as_slice(),[b.address.to_string()]);assert_eq!(b.targets.lock().unwrap().as_slice(),[target.to_string()]);stopped(&session,weak,ports).await;servers.close().await;
}
#[tokio::test(flavor="multi_thread",worker_threads=4)]
async fn stopping_held_projection_fetch_preserves_last_good_cache_and_never_dials_candidate_hops(){
    let _serial=LOCK.lock().await;let roots=root_fixture::Roots::new();let mut servers=Servers::new();let a=servers.proxy().await;let b=servers.proxy().await;let c=servers.proxy().await;let d=servers.proxy().await;let feed=servers.feed(filtered_payload(a.address.port(),b.address.port(),"old")).await;
    let yaml=format!("strict: true\nproxy-providers: {{feed: {{type: http,url: 'http://{}/feed',path: held-cache.yaml,interval: 0}}}}\nproxy-groups:\n - {{name: FRONT,type: select,use: [feed],filter: '^front-'}}\n - {{name: PICK,type: select,use: [feed],filter: '^exit-'}}\nrules: ['MATCH,PICK']\n",feed.address);let ports=ports().await;let(session,weak)=start(plan(&yaml,ports,&roots.read,&roots.cache));timeout(Duration::from_secs(5),session.ready()).await.unwrap().unwrap();let cache=std::fs::read(roots.cache.join("held-cache.yaml")).unwrap();let owner=session.owned_runtime().unwrap();let stamp=owner.route_stamp();
    *feed.payload.write().await=filtered_payload(c.address.port(),d.address.port(),"new");feed.hold.store(true,Ordering::Release);let private=ports[0];let pending=tokio::spawn(async move{request_result(private,"PUT","/providers/proxies/feed","").await});timeout(Duration::from_secs(5),feed.started.notified()).await.unwrap();stopped(&session,weak,ports).await;let response=timeout(Duration::from_secs(5),pending).await.unwrap().unwrap();assert!(response.is_err()||!response.unwrap().starts_with("HTTP/1.1 204"));timeout(Duration::from_secs(5),feed.eof.notified()).await.unwrap();assert_eq!(std::fs::read(roots.cache.join("held-cache.yaml")).unwrap(),cache);assert_eq!(owner.route_stamp(),stamp);for peer in [&a,&b,&c,&d]{assert!(peer.targets.lock().unwrap().is_empty());}servers.close().await;
}
